import torch
import torch.nn.functional as F


def gen_inputs(ctx, device):
    torch.manual_seed(1234567890)
    result = {}
    for name in ("query", "key", "value"):
        shape = tuple(ctx[f"{name}__shape"])
        dtype = getattr(torch, ctx[f"{name}__dtype"])
        result[name] = torch.empty(shape, dtype=dtype, device=device).uniform_(-0.05, 0.05).requires_grad_()
    grad_shape = tuple(ctx["grad_output__shape"])
    grad_dtype = getattr(torch, ctx["grad_output__dtype"])
    result["grad_output"] = torch.randn(grad_shape, dtype=grad_dtype, device=device)
    return result


def run(grad_output, query, key, value, scale, is_causal, enable_gqa):
    q = query.detach().requires_grad_(True)
    k = key.detach().requires_grad_(True)
    v = value.detach().requires_grad_(True)
    output = F.scaled_dot_product_attention(
        q,
        k,
        v,
        attn_mask=None,
        dropout_p=0.0,
        is_causal=is_causal,
        scale=scale,
        enable_gqa=enable_gqa,
    )
    return torch.autograd.grad(output, (q, k, v), grad_outputs=grad_output)


def _assert_close_equal_nan(actual, expected, rtol, atol):
    try:
        torch.testing.assert_close(
            actual,
            expected.to(actual.dtype),
            rtol=rtol,
            atol=atol,
            equal_nan=True,
        )
        return ""
    except AssertionError as exc:
        return str(exc)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    if len(ref_outputs) != 3 or len(sol_outputs) != 3:
        return {"passed": False, "message": "expected dQ, dK, dV", "metrics": {}}
    dtype_name = ctx["query__dtype"]
    rtol = {
        "float16": 1e-3,
        "bfloat16": 0.016,
        "float32": 1.3e-6,
        "float64": 1e-7,
    }.get(dtype_name, 1.3e-6)
    for index, label in ((0, "dQ"), (1, "dK")):
        message = _assert_close_equal_nan(sol_outputs[index], ref_outputs[index], rtol, 1e-4)
        if message:
            return {"passed": False, "message": f"{label}: {message}", "metrics": {}}
    is_gqa = bool(ctx["enable_gqa"]) and inputs[1].shape[1] != inputs[2].shape[1]
    if is_gqa:
        v_atol = 2e-2 if dtype_name == "bfloat16" else 4e-3 if dtype_name == "float16" else 5e-4
    else:
        v_atol = 5e-3 if dtype_name == "bfloat16" else 2e-3 if dtype_name == "float16" else 3e-4
    message = _assert_close_equal_nan(sol_outputs[2], ref_outputs[2], rtol, v_atol)
    if message:
        return {"passed": False, "message": f"dV: {message}", "metrics": {}}
    return {"passed": True, "message": "", "metrics": {}}
